class Solution {
public:
    std::vector<std::string> allPrefixesAndSubstrings(std::string str) {
        if (str.empty()){
            throw std::invalid_argument("Input cannot be null or empty");
        }

        std::vector<std::string> result;
        std::istringstream iss(str);
        std::string word, prefix;
        while (iss >> word) {
            prefix += word + " ";
            for (size_t i = 1; i <= word.size(); i++) {
                result.push_back(word.substr(0, i));
            }
            result.push_back(prefix.substr(0, prefix.size()-1)); //trim the last whitespace
        }

        std::sort(result.begin(), result.end(),
            [](const std::string &s1, const std::string &s2){
                return s1.size() < s2.size();
            });

        return result;
    }
};

int main() {
    Solution solution;
    std::vector<std::string> results = solution.allPrefixesAndSubstrings("abc def");
    for(const auto &s : results) {
        std::cout << s << "\n";
    }
    return 0;
}", "language": "cpp"}

