{"code": "package main

import (
	"fmt"
	"sort"
)

func strangeSortList(lst []int) []int {
	if len(lst) == 0 {
		return lst
	}

	sort.Ints(lst)
	var result []int
	for len(lst) > 0 {
		// Add smallest
		result = append(result, lst[0])
		lst = lst[1:]

		if len(lst) > 0 {
			// Add largest
			result = append(result, lst[len(lst)-1])
			lst = lst[:len(lst)-1]
		}
	}
	return result
}

func main() {
	fmt.Println(strangeSortList([]int{1, 2, 3, 4})) // [1, 4, 2, 3]
	fmt.Println(strangeSortList([]int{5, 5, 5, 5})) // [5, 5, 5, 5]
	fmt.Println(strangeSortList([]int{}))           // []
}", "language": "go"}
